    },
    {
      "id": "pe-ratio-divergence",
      "insight": "Highlight the comparative magnitude of P/E ratios between the two periods, making it easy to see how current valuations stack up against the dot-com peak"
    },
    {
      "id": "ipo-frenzy-contrast",
      "insight": "Emphasize the difference in IPO volume patterns between the two eras, showing whether the AI period exhibits a comparable surge in new listings"
    },
    {
      "id": "earnings-backdrop",
      "insight": "Show aggregate NASDAQ corporate earnings as a backdrop to valuations in both periods, making it visually clear whether earnings growth supports or contradicts the price run-up"
    },
    {
      "id": "peak-markers",
      "insight": "Mark the dot-com NASDAQ peak (March 2000) and the AI-era recent high on the aligned timeline so viewers can anchor the comparison around climax points"
    }
  ]
}

