cat << 'EOF' > generate_mermaid.py
import json

def load_data():
    with open('/app/benchmark/source_data.json') as f:
        return json.load(f)

data = load_data()

# Process NASDAQ
nasdaq = data['nasdaq_index']['data']
nasdaq_dotcom = [None] * 24
nasdaq_ai = [None] * 16

for d in nasdaq:
    offset = d['quarter_offset']
    val = d['index_value']
    if d['era'] == 'Dot-com':
        nasdaq_dotcom[offset] = val
    else:
        nasdaq_ai[offset] = val

# Process P/E
pe = data['pe_ratio']['data']
pe_dotcom = [None] * 24
pe_ai = [None] * 16

for d in pe:
    offset = d['quarter_offset']
    val = d['pe']
    if d['era'] == 'Dot-com':
        pe_dotcom[offset] = val
    else:
        pe_ai[offset] = val

def interpolate(arr):
    last_val = arr[0]
    last_idx = 0
    for i in range(1, len(arr)):
        if arr[i] is not None:
            diff = arr[i] - last_val
            steps = i - last_idx
            for j in range(1, steps):
                arr[last_idx + j] = round(last_val + diff * (j / steps), 1)
            last_val = arr[i]
            last_idx = i
    return arr

interpolate(pe_dotcom)
interpolate(pe_ai)

# Process IPOs
ipos = data['ipo_counts']['data']
ipo_dotcom = [None] * 24
ipo_ai = [None] * 16

for d in ipos:
    year = d['year']
    val = d['ipo_count']
    if d['era'] == 'Dot-com':
        offset = (year - 1997) * 4
        ipo_dotcom[offset] = val
    else:
        offset = (year - 2021) * 4
        ipo_ai[offset] = val

interpolate(ipo_dotcom)
interpolate(ipo_ai)

# Process Earnings
earn = data['corporate_earnings']['data']
earn_dotcom = [None] * 24
earn_ai = [None] * 16

for d in earn:
    year = d['year']
    val = d['earnings_bn']
    if d['era'] == 'Dot-com':
        offset = (year - 1997) * 4
        earn_dotcom[offset] = val
    else:
        offset = (year - 2021) * 4
        earn_ai[offset] = val

interpolate(earn_dotcom)
interpolate(earn_ai)

def arr_to_str(arr):
    while arr and arr[-1] is None:
        arr.pop()
    return "[" + ", ".join(str(x) for x in arr) + "]"

labels = []
for i in range(24):
    if i == 12:
        labels.append("Q12 (Dot-com Peak)")
    elif i == 15:
        labels.append("Q15 (AI Peak)")
    else:
        labels.append(f"Q{i}")

x_axis = "[" + ", ".join(f'"{label}"' for label in labels) + "]"

theme = "%%{init: { \"themeVariables\": { \"xyChart\": { \"plotColorPalette\": \"#E37222,#0055A4\" } } } }%%"

md = f"""
# Dot-com vs AI Era Comparisons

## NASDAQ Index
```mermaid
{theme}
xychart-beta
    title "NASDAQ Trajectory (Base=100)"
    x-axis {x_axis}
    y-axis "Index Value" 50 --> 320
    line {arr_to_str(nasdaq_dotcom)}
    line {arr_to_str(nasdaq_ai)}
```

## P/E Ratio
```mermaid
{theme}
xychart-beta
    title "NASDAQ P/E Ratio Divergence (Trailing 12-month)"
    x-axis {x_axis}
    y-axis "P/E Ratio (x)" 20 --> 110
    line {arr_to_str(pe_dotcom)}
    line {arr_to_str(pe_ai)}
```

## IPO Count
```mermaid
{theme}
xychart-beta
    title "Tech IPO Frenzy Contrast (Annual totals, interpolated)"
    x-axis {x_axis}
    y-axis "Number of IPOs" 0 --> 350
    line {arr_to_str(ipo_dotcom)}
    line {arr_to_str(ipo_ai)}
```

## Corporate Earnings
```mermaid
{theme}
xychart-beta
    title "NASDAQ-100 Corporate Earnings ($ Billions, Nominal) Backdrop"
    x-axis {x_axis}
    y-axis "Net Income ($B)" -50 --> 550
    line {arr_to_str(earn_dotcom)}
    line {arr_to_str(earn_ai)}
```
"""

with open('benchmark.md', 'w') as f:
    f.write(md)
EOF
